  Lemma alloc_sec_t1c : forall (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word) (mX : mem) (j8 : list byte) (ob0 : byte) (hb1 nd8 : Z),
    needed = 8 * nd8 ->
    AENV tp TSD CTX TH sb SO T rest mX -> mem_inv bsegs mX ->
    AFR mX j8 -> stk bsegs mX lo (bv_unsigned sp + -128) ->
    rw_cells bsegs mX (a + 6128) [C1 ob0; C1 (b8 hb1); C2 (wz 0); C4 (wz size); C8 (wz id)] -> 0 <= hb1 < 256 -> b1_ok (Z.land hb1 243) ->
    stk bsegs mX (a + 4096) (a + 6128) -> stk bsegs mX (a + 6144) (a + msz) ->
    rw_cells bsegs mX (AINST + 64) [C8 (wz 4096); C8 (wz pa); C8 (wz pa)] ->
    rw_cells bsegs mX a [C8 (wz a); C8 (wz msz); C8 (wz needed); C8 (wz nch)] ->
    stk bsegs mX (sh (a + 4096)) (sh (a + 4096) + nd8) ->
    u8arr bsegs mX (sh (a + 4096) + nd8) (repeat (b8 0xfa) (Z.to_nat ((msz - 4096 - needed) / 8))) ->
    stk bsegs mX (TH + 2800) (TH + 3168) ->
    DEPOT bsegs (d_put d (depot_hash T) nT) mX ->
    evt bsegs (alloc_sec_t1_post sp gp tp F fc mX W lo size a msz needed q8 r8 SO TH id pa nch TSD CTX sb T rest (d_put d (depot_hash T) nT) AFR)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp x5 x6 x7 (wz 0) (wz size) (wz sb) x11 x12 x13 x14 x15 x16 x17
               (wz (a + 4096)) (wz needed) (wz (a + 6144)) (wz (a + 6128)) (wz AINST) (wz SO) (wz 0) (wz (a + 6144 + size)) (wz TH) (wz 1) x28 x29 x30 x31)
